/**
 * views/briefing.js
 *
 * The Briefing tab — the paste-ready output of the "Met Irma" pipeline.
 *
 * Each day (next 7) shows two generated Dutch texts:
 *   1. a Caren cluster line (pasted into Caren → Nedap Luna display), and
 *   2. a WhatsApp evening-reminder draft (forwarded in the family group).
 *
 * Texts are generated by the private irma-sync job and are read-only here.
 * Members can only copy them and flip the "sent" status. The actual paste and
 * send are always performed by a human — this view ends at ready-to-paste text.
 *
 * Owners additionally see a Caren *reconciliation* section per card: whether a
 * Caren notification e-mail has been seen for each expected appointment. That
 * is a completely separate axis from the "Markeer als verzonden" workflow
 * below, which stays a human decision and is never changed by Caren evidence.
 * The Caren enrichment loads independently, and a failure to load it leaves
 * the briefing text itself untouched.
 */

import {
  fetchBriefings, markBriefingSent, reopenBriefing,
  fetchCarenExpectedItems, fetchCarenEvidence, fetchLatestCarenRun, reviewCarenItem,
} from '../api.js';
import { getState }   from '../state.js';
import { escapeHtml } from '../utils.js';
import { openCarenCompareModal } from '../components/caren-compare-modal.js';
import { carenFreshness, carenErrorCode, carenErrorText } from '../lib/caren-status.js';
import { carenSectionForViewer } from '../lib/caren-render.js';
import { formatRelative, formatDateKeyHeader, formatDayHeader, formatTime } from '../lib/datetime.js';

const STATUS_BADGE = {
  ready:              { label: 'Klaar',                     cls: 'briefing-badge--ready'   },
  sent:               { label: 'Verzonden ✓',          cls: 'briefing-badge--sent'    },
  changed_after_sent: { label: 'Gewijzigd na verzending!',  cls: 'briefing-badge--changed' },
};

/** Amsterdam-local "day at time" for an ISO instant. */
function formatMoment(iso) {
  if (!iso) return '';
  return `${formatDayHeader(iso)} om ${formatTime(iso)}`;
}

/**
 * @param {HTMLElement} container
 * @param {{ familyId: string|null, accessType?: string|null }} state
 */
export async function mount(container, { familyId, accessType }) {
  const isOwner = accessType === 'owner';

  container.innerHTML = `
    <div class="view-briefing">
      <div class="view-header">
        <h1>Briefing</h1>
      </div>
      <div id="briefing-content">
        <div class="section-loading">Briefings laden…</div>
      </div>
    </div>
  `;

  const contentEl = container.querySelector('#briefing-content');

  if (!familyId) {
    contentEl.innerHTML = '<p class="empty-state">Familie niet gevonden.</p>';
    return;
  }

  /** @type {Array} */
  let briefings = [];
  /** @type {Map<string, Array>} briefing id → its active expected items */
  let carenItemsByBriefing = new Map();
  /** @type {Map<string, object>} evidence id → evidence row */
  let carenEvidenceById = new Map();
  /** @type {{level: string, note: string|null}} */
  let carenFresh = { level: 'disabled', note: null };
  let carenAvailable = false;

  async function load() {
    try {
      briefings = await fetchBriefings(familyId, { limit: 7 });
    } catch (err) {
      console.error('[ma/briefing] Failed to load briefings:', err);
      contentEl.innerHTML =
        '<p class="empty-state">Kon de briefings niet laden. Probeer het opnieuw.</p>';
      return;
    }
    // Briefing text is on screen regardless of what happens next: Caren is
    // optional enrichment and must never be able to blank this page.
    if (isOwner && briefings.length) await loadCarenEnrichment();
    render();
  }

  /**
   * Load the Caren layer independently of the briefings themselves. Every
   * failure mode here — migration 014 not applied, RLS denying a non-owner,
   * a network blip — degrades to "no Caren section", never to a broken page.
   */
  async function loadCarenEnrichment() {
    const briefingIds = briefings.map(b => b.id);
    const [itemsResult, runResult] = await Promise.allSettled([
      fetchCarenExpectedItems(briefingIds),
      fetchLatestCarenRun(familyId),
    ]);

    if (itemsResult.status !== 'fulfilled') {
      console.error('[ma/briefing] Caren reconciliation unavailable:', itemsResult.reason);
      carenAvailable = false;
      return;
    }
    carenAvailable = true;

    carenItemsByBriefing = new Map();
    for (const item of itemsResult.value) {
      const list = carenItemsByBriefing.get(item.briefing_id) ?? [];
      list.push(item);
      carenItemsByBriefing.set(item.briefing_id, list);
    }

    carenFresh = carenFreshness(runResult.status === 'fulfilled' ? runResult.value : null);

    // Evidence is a separate, equally optional fetch: without it the rows
    // still render, just without the "wijziging · dinsdag om 09:12" line.
    const evidenceIds = itemsResult.value
      .flatMap(item => [item.matched_evidence_id, item.ambiguous_evidence_id])
      .filter(Boolean);
    try {
      const evidence = await fetchCarenEvidence([...new Set(evidenceIds)]);
      carenEvidenceById = new Map(evidence.map(row => [row.id, row]));
    } catch (err) {
      console.error('[ma/briefing] Caren evidence unavailable:', err);
      carenEvidenceById = new Map();
    }
  }

  function carenSectionFor(briefing) {
    return carenSectionForViewer(carenItemsByBriefing.get(briefing.id) ?? [], {
      accessType,
      available: carenAvailable,
      freshness: carenFresh,
      evidenceById: carenEvidenceById,
      formatMoment,
    });
  }

  function render() {
    if (!briefings.length) {
      contentEl.innerHTML =
        '<p class="empty-state">Nog geen briefings. De synchronisatie draait elke drie uur en kan door een beheerder handmatig worden gestart.</p>';
      return;
    }
    contentEl.innerHTML = briefings.map(b => renderCard(b, carenSectionFor(b))).join('');
    wire();
  }

  function wire() {
    // Copy buttons — write to clipboard inside the user gesture (iOS Safari).
    contentEl.querySelectorAll('[data-copy]').forEach(btn => {
      btn.addEventListener('click', () => {
        const briefing = briefings.find(b => b.id === btn.dataset.id);
        if (!briefing) return;
        const text = btn.dataset.copy === 'caren'
          ? briefing.caren_text
          : briefing.whatsapp_text;
        copyToClipboard(btn, text);
      });
    });

    // Sent / reopen toggle — untouched by anything Caren does.
    contentEl.querySelectorAll('[data-toggle]').forEach(btn => {
      btn.addEventListener('click', () => toggleSent(btn));
    });

    contentEl.querySelectorAll('[data-caren-item]').forEach(btn => {
      btn.addEventListener('click', () => onCarenAction(btn));
    });
  }

  function findCarenItem(itemId) {
    for (const items of carenItemsByBriefing.values()) {
      const found = items.find(i => i.id === itemId);
      if (found) return found;
    }
    return null;
  }

  /** Replace one item in place after a review, then re-render. */
  function applyCarenUpdate(updated) {
    if (!updated) return;
    const items = carenItemsByBriefing.get(updated.briefing_id);
    if (items) {
      const index = items.findIndex(i => i.id === updated.id);
      if (index >= 0) items[index] = { ...items[index], ...updated };
    }
    render();
  }

  async function onCarenAction(btn) {
    const item = findCarenItem(btn.dataset.carenItem);
    if (!item) return;

    if (btn.dataset.carenAction === 'compare') {
      const evidence = carenEvidenceById.get(btn.dataset.carenEvidence);
      if (!evidence) {
        showCarenError(btn, 'caren_invalid_evidence');
        return;
      }
      openCarenCompareModal(item, evidence, {
        formatMoment,
        formatDay: formatDayHeader,
        onDecision: async (decision) => {
          try {
            applyCarenUpdate(await reviewCarenItem({
              itemId: item.id, action: decision, evidenceId: evidence.id,
            }));
          } catch (err) {
            console.error('[ma/briefing] Caren review failed:', err);
            throw new Error(carenErrorText(carenErrorCode(err)));
          }
        },
      });
      return;
    }

    const action = btn.dataset.carenAction;
    const confirmCopy = action === 'manual_confirm'
      ? 'Ik bevestig dat deze afspraak in Caren staat.'
      : 'Weet je zeker dat je deze controle wilt heropenen?';
    if (!window.confirm(confirmCopy)) return;

    btn.disabled = true;
    try {
      applyCarenUpdate(await reviewCarenItem({ itemId: item.id, action, evidenceId: null }));
    } catch (err) {
      console.error('[ma/briefing] Caren review failed:', err);
      showCarenError(btn, carenErrorCode(err));
      btn.disabled = false;
    }
  }

  function showCarenError(btn, code) {
    const row = btn.closest('.caren-item');
    if (!row) return;
    let el = row.querySelector('.caren-item-error');
    if (!el) {
      el = document.createElement('p');
      el.className = 'caren-item-error';
      row.appendChild(el);
    }
    el.textContent = carenErrorText(code);
  }

  async function toggleSent(btn) {
    const briefing = briefings.find(b => b.id === btn.dataset.id);
    if (!briefing) return;

    const wasSent = briefing.status === 'sent';
    const userId  = getState().user?.id ?? null;

    btn.disabled = true;
    try {
      const updated = wasSent
        ? await reopenBriefing(briefing.id)
        : await markBriefingSent(briefing.id, userId);
      Object.assign(briefing, updated);
      render();
    } catch (err) {
      console.error('[ma/briefing] Failed to update status:', err);
      btn.disabled = false;
      btn.textContent = 'Kon status niet wijzigen';
    }
  }

  await load();
}

/**
 * Copies `text`, flashing the button label to confirm. iOS Safari requires
 * the writeText call to happen inside the click handler's user gesture.
 */
function copyToClipboard(btn, text) {
  const restore = btn.textContent;
  navigator.clipboard.writeText(text ?? '').then(() => {
    btn.textContent = 'Gekopieerd ✓';
    btn.classList.add('briefing-copy--done');
    setTimeout(() => {
      btn.textContent = restore;
      btn.classList.remove('briefing-copy--done');
    }, 1500);
  }).catch(err => {
    console.error('[ma/briefing] Clipboard write failed:', err);
    btn.textContent = 'Kopiëren mislukt';
    setTimeout(() => { btn.textContent = restore; }, 1500);
  });
}

/**
 * Renders one day's briefing card as an HTML string. Everything user-facing is
 * escaped; generated texts are shown with their line breaks preserved via CSS.
 *
 * `carenSection` is pre-rendered HTML (already escaped by lib/caren-render.js)
 * and is empty for every non-owner.
 */
function renderCard(b, carenSection = '') {
  const badge = STATUS_BADGE[b.status] ?? STATUS_BADGE.ready;
  const toggleLabel = b.status === 'sent' ? 'Heropen' : 'Markeer als verzonden';

  const carenBlock = b.caren_text
    ? `
      <div class="briefing-block">
        <div class="briefing-block-head">
          <span class="briefing-block-label">Caren</span>
          <button class="briefing-copy" data-copy="caren" data-id="${escapeHtml(b.id)}">
            Kopieer Caren-regel
          </button>
        </div>
        <pre class="briefing-text briefing-text--mono">${escapeHtml(b.caren_text)}</pre>
      </div>`
    : '';

  const whatsappBlock = b.whatsapp_text
    ? `
      <div class="briefing-block">
        <div class="briefing-block-head">
          <span class="briefing-block-label">WhatsApp</span>
          <button class="briefing-copy" data-copy="whatsapp" data-id="${escapeHtml(b.id)}">
            Kopieer WhatsApp-bericht
          </button>
        </div>
        <pre class="briefing-text">${escapeHtml(b.whatsapp_text)}</pre>
      </div>`
    : '';

  return `
    <article class="briefing-card">
      <header class="briefing-card-head">
        <h2 class="briefing-date">${escapeHtml(formatDateKeyHeader(b.briefing_date))}</h2>
        <span class="briefing-badge ${badge.cls}">${escapeHtml(badge.label)}</span>
      </header>
      ${carenBlock}
      ${whatsappBlock}
      <div class="briefing-actions">
        <button class="briefing-toggle" data-toggle data-id="${escapeHtml(b.id)}">
          ${escapeHtml(toggleLabel)}
        </button>
      </div>
      ${carenSection}
      <footer class="briefing-foot">
        Laatst bijgewerkt: ${escapeHtml(formatRelative(b.generated_at))}
      </footer>
    </article>
  `;
}
